// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler, ClonesWithImmutableArgs} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address owner_, address collateral_) public {
        vm.assume(owner_ != collateral_);

        bytes memory data = abi.encodePacked(owner_, collateral_);
        address payable cc = ClonesWithImmutableArgs.clone(address(c), data);

        assertTrue(Cooler(payable(cc)).owner() == owner_);
    }
}
